-- PT109-S1-Q2. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT109-S1-Q2$batch05$ AND q.stimulus=$batch05$Sheila: It has been argued that using computer technology to add color to a movie originally filmed in black and white damages the integrity of the original film. But no one argues that we should not base a movie on a novel or a short story because doing so would erode the value of the book or story. The film adaptation of the written work is a new work that stands on its own. Judgments of it do not reflect on the original. Similarly, the colorized film is a new work distinct from the original and should be judged on its own merit. It does not damage the integrity of the original black-and-white film.$batch05$ AND q.prompt=$batch05$Sheila's argument uses which one of the following techniques of argumentation?$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT109-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT109-S1-Q2$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT109-S1-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Sheila) A colorized film does not damage the integrity of the original black-and-white film.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$A movie based on a novel is a new work that stands on its own and does not harm the book. A colorized film is similarly a new, separate work.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Sheila takes a case everyone agrees on (adaptations do not harm their source books) and argues that colorized films are like it. "Similarly" is the giveaway. Two cases share a feature (each is a new work), so they should share a conclusion (no harm to the original). That is an analogy.$batch05$), (3, $batch05$Goal$batch05$, $batch05$An analogy between similar cases.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT109-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The adaptation and the colorized film are the similar cases. What Sheila agrees about one (no harm to the original), she carries to the other.$batch05$), ($batch05$B$batch05$, $batch05$This is the most popular wrong answer, and the difference is worth learning. A counterexample is one case that breaks a general claim. An analogy uses one case to support a conclusion about another. Sheila is not trying to break the principle "colorizing damages the original." She is building support for her view through a matching case.$batch05$), ($batch05$C$batch05$, $batch05$"No one argues" sounds like popular opinion, but Sheila's support is the similarity between the cases, not what most people think.$batch05$), ($batch05$D$batch05$, $batch05$No line is drawn between facts and value judgments.$batch05$), ($batch05$E$batch05$, $batch05$Sheila argues from a parallel case, not from a general principle.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT109-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
